// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 sequenceNumber_,
        bytes32 batcherHash_,
        uint256 l1FeeOverhead_,
        uint256 l1FeeScalar_
    ) public {
        // Only the depositor account (address(0), the initialized value of the
        // public depositorAccount variable) may call setL1BlockValues.
        vm.prank(address(0));
        c.setL1BlockValues(
            number_,
            timestamp_,
            basefee_,
            hash_,
            sequenceNumber_,
            batcherHash_,
            l1FeeOverhead_,
            l1FeeScalar_
        );
        // General rule: the reference never writes batcherHash, so it stays zero
        // for every admissible input; the mutant stores the fuzzed value.
        assertTrue(c.batcherHash() == bytes32(0));
    }
}
